#!/usr/bin/env bash
set -euo pipefail

# Generates a GitHub release body from packaged artifacts and the changes
# generated by the GitHub release-notes API.
#
# Usage: generate-release-notes.sh <upload-dir> <changes-file> [previous-tag]
# Env:   GITHUB_REPOSITORY, GITHUB_SHA, GITHUB_RUN_ID, GITHUB_RUN_NUMBER,
#        RELEASE_VERSION, RELEASE_TAG

script_dir="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
# shellcheck source=scripts/release/artifact-notes.sh
source "${script_dir}/artifact-notes.sh"

upload_dir="${1:?usage: generate-release-notes.sh <upload-dir> <changes-file> [previous-tag]}"
changes_file="${2:?usage: generate-release-notes.sh <upload-dir> <changes-file> [previous-tag]}"
previous_tag="${3:-}"
repo="${GITHUB_REPOSITORY:?GITHUB_REPOSITORY required}"
sha="${GITHUB_SHA:?GITHUB_SHA required}"
run_id="${GITHUB_RUN_ID:?GITHUB_RUN_ID required}"
run_number="${GITHUB_RUN_NUMBER:?GITHUB_RUN_NUMBER required}"
tag="${RELEASE_TAG:?RELEASE_TAG required}"
version="${RELEASE_VERSION:?RELEASE_VERSION required}"
version="${version#v}"

base="https://github.com/${repo}/releases/download/${tag}"
commit_url="https://github.com/${repo}/commit/${sha}"
run_url="https://github.com/${repo}/actions/runs/${run_id}"
sha_short="${sha:0:7}"
date_utc="$(date -u +%Y-%m-%dT%H:%M:%SZ)"
checksum_name="mssh-${version}-SHA256SUMS"

printf '## 🚀 MSSH `%s`\n\n' "${tag}"
printf '> 正式发布于 **%s**。\n\n' "${date_utc}"
printf -- '- **提交**: `%s`（[查看提交](%s)）\n' "${sha_short}" "${commit_url}"
printf -- '- **构建**: [GitHub Actions 运行 #%s](%s)\n' "${run_number}" "${run_url}"
if [[ -n "${previous_tag}" ]]; then
  printf -- '- **变更范围**: [`%s...%s`](https://github.com/%s/compare/%s...%s)\n' \
    "${previous_tag}" "${tag}" "${repo}" "${previous_tag}" "${tag}"
fi
printf '\n'

print_artifact_tables

printf '### 📝 Pull Requests & Changes\n\n'
if [[ -n "${previous_tag}" ]]; then
  printf '以下内容由 GitHub 自动汇总 `%s...%s` 范围内的 Pull Request 与变更：\n\n' "${previous_tag}" "${tag}"
fi
if ! grep -Eq '^\* .* by @' "${changes_file}"; then
  printf '_未发现关联的 Pull Request。_\n\n'
fi
sed -E 's/^## /#### /' "${changes_file}" | sed -e :a -e '/^\n*$/{$d;N;ba' -e '}'
printf '\n'

print_checksum_block "${checksum_name}"
